--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -1,7 +1,45 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
+export interface ProvenanceVerification {
+  /** Cryptographic evidence (e.g., GPG signature validation result) */
+  gpgVerified?: boolean;
+  /** Infrastructure evidence (e.g., merge commit, branch protection, code review) */
+  infrastructureVerified?: boolean;
+  /** External metadata from trusted sources */
+  externalMetadata?: string;
+}
+
+/**
+ * Extract claimed provenance from commit trailers, but do not trust it.
+ * Trailers are self-asserted and can be spoofed via git commit --message.
+ */
+export const claimedProvenanceOf = (trailers: ReadonlyMap<string, string>): Provenance | null => {
   const raw = trailers.get("Provenance");
   if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+  return null;
+};
+
+/**
+ * Verify provenance through independent evidence, not self-asserted claims.
+ * Returns the verified provenance level, or "unknown" if unverifiable.
+ *
+ * Security: This only trusts signals that cannot be forged by someone making a commit.
+ * In an offline context without key management, most signals must be "unknown".
+ */
+export const provenanceOf = (
+  _trailers: ReadonlyMap<string, string>,
+  verification?: ProvenanceVerification
+): Provenance => {
+  // If there's cryptographic verification (e.g., valid GPG signature), trust "authored"
+  if (verification?.gpgVerified) return "authored";
+
+  // If there's infrastructure verification (e.g., merge through protected branch,
+  // code review requirement, or CI gate), the commit inherited those properties
+  if (verification?.infrastructureVerified) return "inherited";
+
+  // External metadata from trusted sources (not from commit message)
+  if (verification?.externalMetadata) return "inherited";
+
+  // Default: we cannot verify this commit offline, so provenance is unknown
   return "unknown";
 };
